import{_ as l,o as t,c as o,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-09-04","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-09-04","date":"2024-09-04T00:00:00.000Z","updated":"2024-09-05T00:00:00.000Z","tags":["Ceph","RGW","数据去重","分片","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-04.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-04.md","lastUpdated":1780459816000}'),d={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-04.md"};function n(p,i,r,s,g,a){return t(),o("div",null,[...i[0]||(i[0]=[e("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Gabby（演示者）、Matt、Kyle、Seth等</p><p><strong>会议主题</strong>： ddop（数据去重优化项目）演示及讨论</p><p><strong>会议内容</strong>：</p><ul><li><strong>ddop项目概述</strong>： <ul><li>ddop项目旨在优化Ceph存储中的数据去重功能，提高存储效率和性能。</li><li>第一阶段将支持大于4MB的对象进行去重。</li><li>ddop基于ref计数和manifest共享机制，通过sharding（分片）的方式并行处理数据。</li><li>项目将分为两个阶段：第一阶段基于对象名进行sharding，第二阶段基于md5进行sharding。</li><li>ddop项目将采用多线程并行处理，以提高效率。</li></ul></li><li><strong>ddop项目演示</strong>： <ul><li>Gabby展示了ddop项目的演示过程，包括数据加载、去重操作、统计结果等。</li><li>演示过程中，ddop项目能够有效地减少冗余数据，并提高存储效率。</li><li>会议中讨论了ddop项目的可扩展性、性能优化等方面。</li></ul></li><li><strong>ddop项目讨论</strong>： <ul><li>会议讨论了ddop项目的以下方面： <ul><li><strong>可扩展性</strong>： ddop项目通过sharding的方式，可以实现线性扩展，提高处理效率。</li><li><strong>性能优化</strong>： ddop项目通过并行处理和数据本地化，提高了去重操作的效率。</li><li><strong>适用场景</strong>： ddop项目适合于存储大量数据的场景，例如备份、归档等。</li><li><strong>未来方向</strong>： <ul><li>支持更小的对象去重。</li><li>支持子文件去重。</li><li>将ddop项目与object packing（对象打包）技术结合。</li><li>将ddop项目与erasure coding（冗余编码）技术结合。</li></ul></li></ul></li></ul></li><li><strong>行动计划</strong>： <ul><li>Gabby将整理ddop项目的代码，并提交PR（Pull Request）。</li><li>参会人员将对ddop项目的代码进行审查，并提出改进意见。</li><li>将ddop项目与Ceph存储系统集成，并进行测试。</li></ul></li></ul><p><strong>关键术语</strong>：</p><ul><li>ddop（数据去重优化项目）</li><li>sharding（分片）</li><li>ref计数</li><li>manifest共享</li><li>md5</li><li>object packing（对象打包）</li><li>erasure coding（冗余编码）</li></ul><p><strong>总结</strong>：</p><p>ddop项目是一个非常有潜力的Ceph存储优化项目，能够有效地提高存储效率和性能。会议中，参会人员对ddop项目进行了详细的讨论，并提出了改进意见。期待ddop项目能够尽快落地，为Ceph存储带来更多价值。</p>",10)])])}const c=l(d,[["render",n]]);export{u as __pageData,c as default};
